import{_ as i,o as a,c as t,a2 as o}from"./chunks/framework.CDA9RsCr.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"en/development/changelog.md","filePath":"en/development/changelog.md","lastUpdated":1794581028000}'),l={name:"en/development/changelog.md"};function n(r,e,s,d,c,h){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="v1-6-0" tabindex="-1">v1.6.0 <a class="header-anchor" href="#v1-6-0" aria-label="Permalink to &quot;v1.6.0&quot;">​</a></h2><p>UI rework and live viewing:</p><ul><li>The lottery page is now a single screen: stream player, room list, danmaku feed and control bar; the sidebar collapses in narrow windows</li><li>New live danmaku panel following the selected room, with Bilibili emotes (including shortcut ones like <code>[oh]</code>), bottom sticking, pause on scroll-up and automatic resume after 3 idle seconds</li><li>New embedded HLS player with a clock watchdog: a silent stall triggers a soft resume first, then a player rebuild with a fresh URL, backing off up to 20s</li><li>Theming reworked into &quot;mode + background preset&quot;: spring-festival and beach backdrops are optional, and the accent is sampled from the active image</li><li>UI moved to Tailwind + HeroUI; scrollbars appear only while scrolling; when results show the stage keeps its aspect ratio and the winners list fills the remaining height inside the card</li><li>Image pipeline: throttled pre-decode queue, Bilibili CDN thumbnails and visibility-gated mounting, cutting main-thread jank during danmaku bursts</li><li>Frontend split by feature (session / lottery / rooms / profiles / settings / history); backend services split into room / danmaku_feed / emote / history</li><li>New browser dev bridge: <code>/api/*</code> and Wails IPC share one set of business code, and the standalone <code>cmd/devbridge</code> reuses the same routes</li><li>Login page gained card tilt and a theme toggle; the QR state machine covers expired and scanned-awaiting-confirmation states</li><li>An empty keyword collects every danmaku; adding a room accepts a pasted live-room link</li></ul><h2 id="v1-5-0" tabindex="-1">v1.5.0 <a class="header-anchor" href="#v1-5-0" aria-label="Permalink to &quot;v1.5.0&quot;">​</a></h2><ul><li>Live participant count on the lottery screen, with an explicit waiting hint</li><li>An empty keyword collects all danmaku; the screen labels the active mode, and no draw happens without participants</li><li>Failed room connections are reported instead of silently &quot;accumulating&quot;</li><li>Copy the winner list in one click from the result screen</li><li>History records the real keyword and winner count, capped at the last 100 entries</li><li>Transient network errors no longer log you out; config files are written with 0600</li></ul><h2 id="v1-4-0" tabindex="-1">v1.4.0 <a class="header-anchor" href="#v1-4-0" aria-label="Permalink to &quot;v1.4.0&quot;">​</a></h2><ul><li><code>getDanmuInfo</code> now uses WBI signing, fixing <code>-352</code> responses that prevented danmaku connections</li><li>The danmaku handshake now includes <code>uid</code> and <code>buvid3</code>, preventing nickname masking and the <code>uid = 0</code> collapse of all participants into one</li><li>Danmaku hosts use <code>wss_port</code> (2245); the legacy <code>getConf</code> fallback keeps the token and host list</li><li>Fixed a stray <code>types</code> entry in the frontend <code>tsconfig.json</code> that surfaced type errors when deps or bindings were missing</li></ul><h2 id="v1-3-0" tabindex="-1">v1.3.0 <a class="header-anchor" href="#v1-3-0" aria-label="Permalink to &quot;v1.3.0&quot;">​</a></h2><ul><li>Draw history expands to show the winner list, sorted newest first with in-card scrolling</li><li>Room input accepts a live-room link and resolves the room ID automatically</li></ul><h2 id="v1-2-0" tabindex="-1">v1.2.0 <a class="header-anchor" href="#v1-2-0" aria-label="Permalink to &quot;v1.2.0&quot;">​</a></h2><ul><li>Windows EXE / NSIS installers built automatically and published with GitHub Releases</li><li>Fixed Windows packaging: npm proxy hangs and NSIS / WebView2 path issues</li></ul><h2 id="v1-1" tabindex="-1">v1.1 <a class="header-anchor" href="#v1-1" aria-label="Permalink to &quot;v1.1&quot;">​</a></h2><ul><li>Draw history is recorded automatically and bound to its profile — switching profiles switches history</li><li>Export the winner list to Markdown in one click, named <code>keyword-count-time</code></li><li>Long winner lists scroll inside the card; the lottery page no longer overflows</li></ul><h2 id="v1-0" tabindex="-1">v1.0 <a class="header-anchor" href="#v1-0" aria-label="Permalink to &quot;v1.0&quot;">​</a></h2><ul><li>Docs site launched, bilingual (zh / en), auto-deployed to GitHub Pages</li><li>Architecture and data-flow redrawn with Mermaid; docs fully rewritten</li><li>Fixed message-toast jitter and a QR-login cookie-fetch bug</li></ul><h2 id="v0-9" tabindex="-1">v0.9 <a class="header-anchor" href="#v0-9" aria-label="Permalink to &quot;v0.9&quot;">​</a></h2><ul><li>Added the beach theme, completing the four-theme set (light / dark / spring-festival / beach)</li><li>Light / Dark rebuilt to the Cirrus spec — pure CSS, pill corners, layered shadows</li><li>Built-in zh / en switch, defaulting to Chinese</li></ul><h2 id="v0-8" tabindex="-1">v0.8 <a class="header-anchor" href="#v0-8" aria-label="Permalink to &quot;v0.8&quot;">​</a></h2><ul><li>Upgraded to Wails v3, switched to a Taskfile build</li><li>Backend rewritten in layers: app → service → domain + event; service no longer depends on Wails</li><li>Removed the unused dynamic-lottery dead code</li><li><code>live:user_join</code> events drive the participant count in real time</li></ul><h2 id="v0-7" tabindex="-1">v0.7 <a class="header-anchor" href="#v0-7" aria-label="Permalink to &quot;v0.7&quot;">​</a></h2><ul><li>Multiple draw profiles, each with its own keyword, rooms and background — switch with one click</li><li>QR-code login, alongside Cookie login</li><li>Auto-reconnect on dropped danmaku connections</li></ul><h2 id="v0-6" tabindex="-1">v0.6 <a class="header-anchor" href="#v0-6" aria-label="Permalink to &quot;v0.6&quot;">​</a></h2><ul><li>First release: danmaku monitoring, keyword matching, UID dedup, random draw</li></ul>',24)])])}const m=i(l,[["render",n]]);export{p as __pageData,m as default};
